package com.neuroflow.task.entity;
import com.neuroflow.subject.entity.Subject;import com.neuroflow.user.entity.User;import jakarta.persistence.*;import java.time.*;import java.util.UUID;import lombok.Getter;import lombok.Setter;
@Getter @Setter @Entity @Table(name="tasks", indexes=@Index(name="idx_tasks_user_status_due_date", columnList="user_id,status,due_date"))
public class Task { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id") private Subject subject; @Column(nullable=false,length=160) private String title; @Column(columnDefinition="text") private String description; @Column(nullable=false,length=20) private String priority; @Column(nullable=false,length=30) private String status; @Column(name="due_date") private LocalDate dueDate; @Column(name="completed_at") private Instant completedAt; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; }
